const $=id=>document.getElementById(id),name=actor=>actor==='asnat'?'Asnat':'Youssef',date=s=>new Date(s).toLocaleString([],{dateStyle:'medium',timeStyle:'short'}),node=(tag,text,cls)=>{const el=document.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el;};
let actor=window.AsechkaActor||localStorage.getItem('vault-actor')||'asnat',deviceId=localStorage.getItem('vault-device')||crypto.randomUUID(),vaults=[],selected=null,session=null,secret='',position=null,watch=null,pulsing=false,opened=false,camera=null,scanning=false,busy=false,uploadBusy=false,blobURLs=[],epoch=0;
