async function api(body,path='/api/vault',grant=false){const r=await fetch(path,{method:body?'POST':'GET',headers:{Accept:'application/json',...(body?{'Content-Type':'application/json','X-Asechka-Vault':'1'}:{}),...(grant&&session?{'X-Asechka-Vault-Grant':session.challenge}:{})},...(body?{body:JSON.stringify({...body,actor})}:{}),cache:'no-store'});let data;try{data=await r.json();}catch{throw new Error('Our vault connection needs a moment.');}if(!r.ok)throw new Error(data.error||'Our vault needs a moment.');return data;}
async function refresh(){try{const v=await api();vaults=v.vaults;render();$('status').textContent='';}catch(e){$('status').textContent=e.message;}}
function render(){const list=$('vault-list');list.replaceChildren();if(!vaults.length)list.append(node('p','A little space for the things we’ll open together.','muted'));for(const v of [...vaults].reverse()){const card=node('article',undefined,'vault-card');card.append(node('span','◇','lock'),node('h2',v.title),node('p',(v.ready?'Ready when we’re together':'Opens '+date(v.opensAt))),node('p',v.notes+' notes · '+v.files.length+' pictures & videos'));const button=node('button',v.ready?'Open together':'Keep something inside');button.onclick=()=>show(v.id);card.append(button);list.append(card);}if(selected)show(selected,false);}
function show(id,scroll=true){const v=vaults.find(v=>v.id===id);if(!v)return;selected=id;$('detail').hidden=false;$('detail-title').textContent=v.title;$('detail-date').textContent='Opens '+date(v.opensAt);$('detail-counts').textContent=v.notes+' sealed notes · '+v.files.length+' pictures & videos';$('additions').hidden=v.ready;$('open-together').disabled=!v.ready||!!session;$('open-together').textContent=v.ready?'Open together ◇':'Waiting for '+date(v.opensAt);if(scroll)$('detail').scrollIntoView({behavior:'smooth',block:'start'});}
$('actor').onchange=()=>{actor=$('actor').value;localStorage.setItem('vault-actor',actor);};
$('new-vault').onclick=()=>{const tomorrow=new Date(Date.now()+86400_000);tomorrow.setMinutes(tomorrow.getMinutes()-tomorrow.getTimezoneOffset());$('opens-at').value=tomorrow.toISOString().slice(0,16);$('create-status').textContent='';$('create-dialog').showModal();};
$('cancel-create').onclick=()=>$('create-dialog').close();
$('create-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;$('create-submit').disabled=true;try{const value=await api({action:'create',operationId:crypto.randomUUID(),title:$('title').value,opensAt:new Date($('opens-at').value).toISOString(),note:$('first-note').value});vaults=value.vaults;selected=vaults.at(-1).id;render();$('create-dialog').close();$('create-form').reset();$('status').textContent='Sealed for our future selves. ♡';}catch(e){$('create-status').textContent=e.message;}finally{busy=false;$('create-submit').disabled=false;}};
$('close-detail').onclick=()=>{$('detail').hidden=true;selected=null;};
$('note-form').onsubmit=async e=>{e.preventDefault();if(busy||!selected)return;busy=true;const button=$('note-form').querySelector('button');button.disabled=true;try{const v=await api({action:'note',vaultId:selected,operationId:crypto.randomUUID(),note:$('note').value});vaults=v.vaults;$('note').value='';render();$('status').textContent='Your note is sealed.';}catch(e){$('status').textContent=e.message;}finally{busy=false;button.disabled=false;}};
const base64=buffer=>{let s='';for(const b of new Uint8Array(buffer))s+=String.fromCharCode(b);return btoa(s);};
$('media').onchange=async()=>{if(uploadBusy||!selected)return;const vaultId=selected,files=[...$('media').files];uploadBusy=true;$('media').disabled=true;try{for(const file of files){if(!file.size||file.size>16*1024*1024)throw new Error(file.name+' is larger than 16 MB. Choose a shorter clip or smaller picture.');const fileId=crypto.randomUUID(),meta={name:file.name.slice(0,150),size:file.size,type:file.type||(/\.heic$/i.test(file.name)?'image/heic':/\.mov$/i.test(file.name)?'video/quicktime':'')},count=Math.ceil(file.size/262144);for(let i=0;i<count;i++){const body={action:'upload',vaultId,fileId,file:meta,index:i,bytes:base64(await file.slice(i*262144,(i+1)*262144).arrayBuffer())};let last;for(let attempt=0;attempt<3;attempt++){try{await api(body);last=null;break;}catch(e){last=e;await new Promise(r=>setTimeout(r,800));}}if(last)throw last;$('upload-status').textContent='Sealing '+file.name+' · '+Math.round((i+1)/count*90)+'%';}$('upload-status').textContent='Finishing '+file.name+'…';const value=await api({action:'finishUpload',vaultId,fileId,file:meta});vaults=value.vaults;render();}$('upload-status').textContent='Sealed safely. You’ll see it when we open this together. ♡';}catch(e){$('upload-status').textContent=e.message+' You can choose the file again.';}finally{uploadBusy=false;$('media').disabled=false;$('media').value='';}};
async function locate(){if(!navigator.geolocation)throw new Error('This device needs location support to open the vault.');return new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(p=>{position={latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy,capturedAt:Math.round(p.timestamp)};resolve(position);},()=>reject(new Error('Allow location permission on both phones, then try again.')),{enableHighAccuracy:true,maximumAge:0,timeout:20000}));}
function observe(){if(watch!==null)return;watch=navigator.geolocation.watchPosition(p=>{position={latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:p.coords.accuracy,capturedAt:Math.round(p.timestamp)};},()=>{$('together-status').textContent='Waiting for a fresh location…';},{enableHighAccuracy:true,maximumAge:0,timeout:20000});}
function clearContents(){epoch++;opened=false;for(const url of blobURLs)URL.revokeObjectURL(url);blobURLs=[];$('contents').hidden=true;$('notes').replaceChildren();$('files').replaceChildren();}
async function end(){const old=session;session=null;secret='';clearContents();if(watch!==null){navigator.geolocation.clearWatch(watch);watch=null;}$('together').hidden=true;$('qr').replaceChildren();$('actor').disabled=false;if(old&&position)fetch('/api/vault',{method:'POST',headers:{'Content-Type':'application/json','X-Asechka-Vault':'1'},body:JSON.stringify({action:'leave',actor,deviceId,challenge:old.challenge,position}),keepalive:true}).catch(()=>{});render();}
function beginSession(value,codeSecret=''){session=value;secret=codeSecret;$('actor').disabled=true;$('together').hidden=false;$('together-title').textContent='Let’s open it together.';$('together-status').textContent=codeSecret?'Ask your partner to scan this code from Time vault on their phone.':'Waiting for the other phone to confirm…';$('qr').replaceChildren();$('qr').hidden=!codeSecret;if(codeSecret){const qr=qrcode(0,'M');qr.addData(JSON.stringify({type:'asechka-vault-v1',challenge:value.challenge,secret:codeSecret}));qr.make();$('qr').innerHTML=qr.createSvgTag({cellSize:6,margin:2,scalable:true});}observe();$('together').scrollIntoView({behavior:'smooth',block:'start'});pulse();}
$('open-together').onclick=async()=>{if(!selected||busy)return;busy=true;$('open-together').disabled=true;try{$('status').textContent='Checking this phone’s location…';const p=await locate(),v=await api({action:'challenge',vaultId:selected,deviceId,position:p});beginSession({...v,vaultId:selected},v.secret);$('status').textContent='';}catch(e){$('status').textContent=e.message;}finally{busy=false;render();}};
async function pulse(){if(!session||pulsing||document.hidden)return;pulsing=true;try{if(!position||Date.now()-position.capturedAt>30000)await locate();const v=await api({action:'pulse',deviceId,challenge:session.challenge,position});if(!session)return;session={...session,...v};if(v.open){$('together-title').textContent='We’re here. Together. ♡';$('together-status').textContent='Keep both phones online, nearby, and on this page. Close & lock when you’re done.';$('qr').hidden=true;if(!opened)await reveal();}else{clearContents();$('together-status').textContent='Waiting for both phones to scan and share a fresh nearby location…';}}catch(e){clearContents();$('together-status').textContent=e.message;}finally{pulsing=false;}}
async function reveal(){const marker=++epoch,v=await api(null,'/api/vault?open='+encodeURIComponent(session.vaultId),true);if(!session||marker!==epoch)return;opened=true;$('contents').hidden=false;$('contents-title').textContent=v.vault.title;$('notes').replaceChildren(...v.vault.notes.map(n=>{const block=node('article',undefined,'vault-note');block.append(node('small',name(n.actor)+' · '+date(n.createdAt)),node('div',n.text));return block;}));$('files').replaceChildren();for(const file of v.vault.files){const box=node('article',undefined,'vault-media'),load=node('button','Reveal '+file.name,'quiet');box.append(load);$('files').append(box);load.onclick=async()=>{load.disabled=true;load.textContent='Opening our little memory…';try{const parts=[];for(let i=0;i<file.chunkCount;i++){if(!session||marker!==epoch)throw new Error('The vault has locked again.');const r=await fetch('/api/vault?vault='+encodeURIComponent(session.vaultId)+'&file='+encodeURIComponent(file.id)+'&chunk='+i,{headers:{'X-Asechka-Vault-Grant':session.challenge},cache:'no-store'});if(!r.ok){let e;try{e=await r.json();}catch{}throw new Error(e?.error||'Open this vault together again.');}parts.push(await r.arrayBuffer());}if(!session||marker!==epoch)return;const url=URL.createObjectURL(new Blob(parts,{type:file.type}));blobURLs.push(url);const media=node(file.type.startsWith('video/')?'video':'img');if(media.tagName==='VIDEO'){media.controls=true;media.playsInline=true;}else media.alt=file.name;media.src=url;box.replaceChildren(media,node('p',file.name+' · kept by '+name(file.actor)));}catch(e){load.textContent=e.message;load.disabled=false;}};}}
$('end-session').onclick=end;
function stopScan(){scanning=false;if(camera)for(const t of camera.getTracks())t.stop();camera=null;$('scan-video').srcObject=null;}
$('cancel-scan').onclick=()=>{stopScan();$('scan-dialog').close();};$('scan-dialog').addEventListener('close',stopScan);
$('scan-code').onclick=async()=>{if(session)await end();$('scan-status').textContent='Point this phone at the code on your partner’s phone.';$('scan-dialog').showModal();try{camera=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});$('scan-video').srcObject=camera;await $('scan-video').play();scanning=true;scanFrame();}catch{$('scan-status').textContent='Allow camera permission to scan the other phone’s QR.';}};
function scanFrame(){if(!scanning)return;const video=$('scan-video'),canvas=$('scan-canvas');if(video.readyState>=2){const width=Math.min(640,video.videoWidth);canvas.width=width;canvas.height=Math.round(video.videoHeight*width/video.videoWidth);const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(video,0,0,canvas.width,canvas.height);const found=jsQR(ctx.getImageData(0,0,canvas.width,canvas.height).data,canvas.width,canvas.height,{inversionAttempts:'dontInvert'});if(found){let code;try{code=JSON.parse(found.data);}catch{}if(code?.type==='asechka-vault-v1'&&/^[\w-]{43}$/.test(code.challenge)&&/^[\w-]{43}$/.test(code.secret)){stopScan();$('scan-dialog').close();join(code);return;}}}requestAnimationFrame(scanFrame);}
