document.addEventListener('visibilitychange',()=>{if(document.hidden&&session)end();});window.addEventListener('pagehide',()=>{stopScan();if(session)end();});window.addEventListener('beforeunload',e=>{if(uploadBusy){e.preventDefault();e.returnValue='';}});setInterval(pulse,8000);setInterval(()=>{if(!document.hidden&&!session)refresh();},30000);refresh();
